import { Button, Field, Input, Stack, Text } from "@chakra-ui/react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../hooks/use-auth";
import { AuthPanel } from "../components/auth-panel";
import { Path } from "@/router/paths";
import { RouterLink } from "@/shared/components/ui/router-link";
import zod from "zod";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { Toaster, toaster } from "@/components/ui/toaster";

const registerSchema = zod.object({
  displayName: zod.string().min(1, "Enter your name"),
  email: zod.string().email("Invalid email address"),
  password: zod.string().min(10, "Use at least 10 characters"),
});

type RegisterFormData = zod.infer<typeof registerSchema>;

export default function RegisterPage() {
  const navigate = useNavigate();
  const { register, error, isLoading } = useAuth();

  const {
    handleSubmit,
    register: registerField,
    formState: { errors },
  } = useForm({
    resolver: zodResolver(registerSchema),
  });

  const onSubmit = async (data: RegisterFormData) => {
    const result = await register(data.email, data.password, data.displayName);
    if (result.success) {
      navigate(Path.Home, { replace: true });
      toaster.success({
        title: `Signed in as ${result.user?.displayName}`,
      });
    }
  };

  return (
    <AuthPanel
      title="Create your account"
      description="Sign up to get started."
      error={error?.message}
      footer={
        <Text>
          Already have an account?{" "}
          <RouterLink to={Path.Login} color="fg" fontWeight="medium">
            Log in
          </RouterLink>
        </Text>
      }
    >
      <form onSubmit={handleSubmit(onSubmit)}>
        <Stack gap="4">
          <Field.Root invalid={!!errors.displayName}>
            <Field.Label>Name</Field.Label>
            <Input
              {...registerField("displayName")}
              autoComplete="name"
              placeholder="Your name"
            />
            <Field.ErrorText>{errors.displayName?.message}</Field.ErrorText>
          </Field.Root>

          <Field.Root invalid={!!errors.email}>
            <Field.Label>Email address</Field.Label>
            <Input
              {...registerField("email")}
              type="email"
              autoComplete="email"
              placeholder="you@example.com"
            />
            <Field.ErrorText>{errors.email?.message}</Field.ErrorText>
          </Field.Root>

          <Field.Root invalid={!!errors.password}>
            <Field.Label>Password</Field.Label>
            <Input
              {...registerField("password")}
              type="password"
              autoComplete="new-password"
              placeholder="Choose a password"
            />
            <Field.ErrorText>{errors.password?.message}</Field.ErrorText>
          </Field.Root>

          <Button type="submit" size="lg" w="full" mt="2" loading={isLoading}>
            Create account
          </Button>
        </Stack>
      </form>
    </AuthPanel>
  );
}
